const PIC = {"B45.png": "data:image/webp;base64,", "B45_motor.png": "data:image/webp;base64,", "BP_lado.jpg": "data:image/webp;base64,", "BP.jpg": "data:image/webp;base64,", "143RS.webp": "data:image/webp;base64,", "143RS_motor.webp": "data:image/webp;base64,", "BC45.png": "data:image/webp;base64,", "BC_lado.png": "data:image/webp;base64,", "BC.png": "data:image/webp;base64,", "BC26_lado.webp": "data:image/webp;base64,", "BC_26.webp": "data:image/webp;base64,", "BK_45.webp": "data:image/webp;base64,", "BK.webp": "data:image/webp;base64,", "T230X.jpg": "data:image/webp;base64,", "T230X-4.jpg": "data:image/webp;base64,", "226.webp": "data:image/webp;base64,", "541_lado.webp": "data:image/webp;base64,", "542.webp": "data:image/webp;base64,", "h210-0256.webp": "data:image/webp;base64,", "g45l.webp": "data:image/webp;base64,", "g45l-2.webp": "data:image/webp;base64,"};
const IMGS = {"B-45": ["B45.png", "B45_motor.png"], "C-35": ["B45.png", "B45_motor.png"], "BP35": ["BP_lado.jpg", "BP.jpg"], "143RS": ["143RS.webp", "143RS_motor.webp"], "BC45": ["BC45.png", "BC_lado.png", "BC.png"], "BC35": ["BC45.png", "BC_lado.png", "BC.png"], "BC26": ["BC26_lado.webp", "BC_26.webp"], "BK45": ["BK_45.webp", "BK.webp"], "BK35": ["BK_45.webp", "BK.webp"], "YB45": ["B45.png", "B45_motor.png"], "YB226": ["226.webp"], "BK4130": ["BK_45.webp", "BK.webp"], "T230": ["T230X.jpg", "T230X-4.jpg"], "226RB": ["226.webp"], "541RB": ["h210-0256.webp", "541_lado.webp"], "G45L": ["g45l-2.webp", "g45l.webp"]};
PRODUCTS.forEach(p => { p.imgs = (IMGS[p.model] || []).map(n => PIC[n]); });
const REF = ["YB45", "YB226", "BK4130"];
PRODUCTS.forEach(p => { p.ref = REF.includes(p.model); });
const $ = s => document.querySelector(s);
const state = {line:"", brand:"", motor:"", q:""};
const lineName = {original:"Línea original", economica:"Línea económica"};
function opts(sel, key){
  [...new Set(PRODUCTS.map(p=>p[key]))].sort().forEach(v=>{
    const o=document.createElement("option"); o.value=v; o.textContent=v; sel.appendChild(o);
  });
}
opts($("#brand"),"brand"); opts($("#motor"),"motor");
function wa(p){
  const t = encodeURIComponent("Hola, me interesa la " + p.brand + " " + p.model + ". ¿Precio y disponibilidad?");
  return "https://wa.me/" + WHATSAPP + "?text=" + t;
}
function render(){
  const q = state.q.trim().toLowerCase();
  const list = PRODUCTS.filter(p =>
    (!state.line || p.line===state.line) && (!state.brand || p.brand===state.brand) &&
    (!state.motor || p.motor===state.motor) &&
    (!q || (p.brand+" "+p.model).toLowerCase().includes(q)));
  $("#count").textContent = list.length + (list.length===1 ? " producto" : " productos");
  $("#grid").innerHTML = list.length ? list.map(p => `
    <article class="card" data-line="${p.line}">
      <div class="photo">${p.imgs.length ? `<img src="${p.imgs[0]}" alt="${p.brand} ${p.model}">` : p.brand.slice(0,2)}${p.ref && p.imgs.length ? '<span class="refbadge">Imagen de referencia</span>' : ""}</div>
      ${p.imgs.length > 1 ? `<div class="thumbs">${p.imgs.map((s,i) => `<button class="th" aria-label="Ver foto ${i+1}"><img src="${s}" alt=""></button>`).join("")}</div>` : ""}
      <div class="body">
        <span class="tag">${lineName[p.line]}</span>
        <h3>${p.model}</h3>
        <div class="brandname">${p.brand}</div>
        <dl>
          <dt>Motor</dt><dd>${p.motor}</dd>
          <dt>Cilindraje</dt><dd>${p.cc ? p.cc + " cc" : "Por confirmar"}</dd>
          <dt>Potencia</dt><dd>${p.hp ? p.hp + " HP" : "Por confirmar"}</dd>
          ${p.uso ? `<dt>Ideal para</dt><dd>${p.uso}</dd>` : ""}
        </dl>
        ${p.feat ? `<ul class="feat">${p.feat.map(f => `<li>${f}</li>`).join("")}</ul>` : ""}
        ${p.acc ? `<details><summary>Qué incluye</summary><p>${p.acc}.</p></details>` : ""}
        <div class="price">${p.price || "Consultar precio"}</div>
        <a class="btn" href="${wa(p)}" target="_blank" rel="noopener">Pedir por WhatsApp</a>
      </div>
    </article>`).join("") : '<p class="empty">No hay productos con ese filtro. Prueba con otra marca o motor.</p>';
}
document.querySelectorAll(".line").forEach(b => b.addEventListener("click", () => {
  const on = b.getAttribute("aria-pressed")==="true";
  document.querySelectorAll(".line").forEach(x => x.setAttribute("aria-pressed","false"));
  state.line = on ? "" : b.dataset.v;
  if(!on) b.setAttribute("aria-pressed","true");
  render();
}));
$("#brand").addEventListener("change", e => {state.brand=e.target.value; render();});
$("#motor").addEventListener("change", e => {state.motor=e.target.value; render();});
$("#q").addEventListener("input", e => {state.q=e.target.value; render();});
$("#grid").addEventListener("click", e => {
  const b = e.target.closest(".th"); if(!b) return;
  b.closest(".card").querySelector(".photo img").src = b.querySelector("img").src;
});
render();
